import Foundation
import XCTest
@testable import TajweedFormer

/// The shared settings vectors of every TajweedFormer SDK (Fixtures/tajweed, generated by the reference settings_ref.py):
/// calibration.json + the portal's tajweed block + app options -> the settings in force, exactly.
final class TajweedSettingsTests: XCTestCase {
    static func fixture(_ name: String) throws -> Data {
        let url = try XCTUnwrap(Bundle.module.url(forResource: name, withExtension: "json", subdirectory: "Fixtures/tajweed"))
        return try Data(contentsOf: url)
    }

    struct Bad: Error {}

    /// App options from the vectors' JSON; an unknown preset, check or option is a Bad (invalid app option).
    static func options(_ v: JSONValue?) throws -> TajweedOptions {
        var o = TajweedOptions()
        guard let d = v?.object else { return o }
        for (k, x) in d {
            switch k {
            case "preset":
                guard let p = x.string.flatMap(TajweedPreset.init(rawValue:)) else { throw Bad() }
                o.preset = p
            case "context":
                guard let s = x.string else { throw Bad() }
                o.context = s
            case "checks":
                for (c, b) in x.object ?? [:] {
                    guard let key = TajweedCheck(rawValue: c), let on = b.bool else { throw Bad() }
                    o.checks[key] = on
                }
            case "overrides":
                for (c, ov) in x.object ?? [:] {
                    let obj = ov.object ?? [:]
                    if obj["preset"] != nil && obj["threshold"] != nil || obj["preset"] == nil && obj["threshold"] == nil { throw Bad() }
                    if let p = obj["preset"] {
                        guard let pp = p.string.flatMap(TajweedPreset.init(rawValue:)) else { throw Bad() }
                        o.overrides[c] = .preset(pp)
                    } else if let t = obj["threshold"]?.number {
                        o.overrides[c] = .threshold(t)
                    } else { throw Bad() }
                }
            default: throw Bad()
            }
        }
        return o
    }

    /// Structural equality of two JSON trees, numbers within 1e-9.
    static func same(_ a: Any, _ b: Any, _ path: String, _ diffs: inout [String]) {
        switch (a, b) {
        case (let x as [String: Any], let y as [String: Any]):
            for k in Set(x.keys).union(y.keys) {
                guard let xv = x[k], let yv = y[k] else { diffs.append("\(path).\(k): missing on one side"); continue }
                same(xv, yv, "\(path).\(k)", &diffs)
            }
        case (let x as [Any], let y as [Any]):
            guard x.count == y.count else { diffs.append("\(path): \(x) vs \(y)"); return }
            for (i, (xv, yv)) in zip(x, y).enumerated() { same(xv, yv, "\(path)[\(i)]", &diffs) }
        case (is NSNull, is NSNull): break
        case (let x as NSNumber, let y as NSNumber):
            let xb = CFGetTypeID(x) == CFBooleanGetTypeID(), yb = CFGetTypeID(y) == CFBooleanGetTypeID()
            if xb != yb || (xb && x.boolValue != y.boolValue) || (!xb && abs(x.doubleValue - y.doubleValue) > 1e-9) {
                diffs.append("\(path): \(x) vs \(y)")
            }
        case (let x as String, let y as String):
            if x != y { diffs.append("\(path): \(x) vs \(y)") }
        default:
            diffs.append("\(path): \(a) vs \(b)")
        }
    }

    func testSharedVectors() throws {
        let cal = try TajweedCalibration(data: Self.fixture("calibration_fixture"))
        let vec = try XCTUnwrap(JSONValue(data: Self.fixture("config_vectors")))
        let cases = try XCTUnwrap(vec["cases"]?.array)
        XCTAssertGreaterThanOrEqual(cases.count, 39)
        for c in cases {
            let name = c["name"]?.string ?? "?"
            let app = try Self.options(c["app"])
            let backend = TajweedBackend(rawValue: c["backend"]?.string ?? "int8") ?? .int8
            let eff = try TajweedSettings.resolve(calibration: cal, remote: c["remote"], app: app,
                                                  debugBuild: c["debug"]?.bool ?? false, backend: backend)
            // round trip through JSONSerialization so both sides are Foundation types
            let got = try JSONSerialization.jsonObject(with: JSONSerialization.data(withJSONObject: eff.jsonObject))
            let want = try XCTUnwrap(c["expect"]).any
            var diffs: [String] = []
            Self.same(got, want, "", &diffs)
            XCTAssertTrue(diffs.isEmpty, "\(name): \(diffs.prefix(6))")
        }
    }

    func testInvalidAppOptionsThrow() throws {
        let cal = try TajweedCalibration(data: Self.fixture("calibration_fixture"))
        let vec = try XCTUnwrap(JSONValue(data: Self.fixture("config_vectors")))
        for c in try XCTUnwrap(vec["app_invalid"]?.array) {
            let name = c["name"]?.string ?? "?"
            let threw: Bool
            do {
                let app = try Self.options(c["app"])
                _ = try TajweedSettings.resolve(calibration: cal, remote: nil, app: app, debugBuild: false)
                threw = false
            } catch {
                threw = true
            }
            XCTAssertTrue(threw, "\(name) did not throw")
        }
    }

    func testWholeConfigDocumentAndNonJSON() {
        let doc = Data(#"{"model":{"id":"v4.0"},"tajweed":{"v":1,"preset":"strict","x":1}}"#.utf8)
        let (b, dropped) = RemoteTajweedBlock.parse(configData: doc)
        XCTAssertEqual(b?.preset, .strict)
        XCTAssertEqual(dropped, ["remote.x"])
        XCTAssertNil(RemoteTajweedBlock.parse(configData: Data("not json".utf8)).block)
        XCTAssertNil(RemoteTajweedBlock.parse(configData: Data(#"{"other":1}"#.utf8)).block)
    }
}
